mapper.select:
    	/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateSum */
        SELECT
		    IFNULL(SUM(GC.CNTR_AMT), 0) AS CNTR_AMT
		    , IFNULL(COUNT(DISTINCT(USER_ID)), 0) AS GIVE_PERSONS
		    , IFNULL(SUM(GC.CNTR_POINT), 0) AS CNTR_POINT
		    , (
		    	SELECT IFNULL(SUM(CNTR_USE_POINT), 0)
		    	FROM G_CNTR_USE_POINT
		    	WHERE use_se_code ='1'

					AND cntr_locgov_code = #{shLocgovCode}


					AND year(point_use_de) = #{shCntrYear}

		      ) AS CNTR_USE_POINT
		FROM G_CNTR GC
		WHERE 1=1
		AND GC.DELETE_AT = 'N'
		and GC.cntr_sttus_code = '200'
        and GC.sttemnt_pay_de is not NULL

		AND year(GC.CNTR_DE) = #{shCntrYear}


		AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode}

/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateListCount */ SELECT COUNT(*) FROM ( SELECT year(GC.CNTR_DE) as CNTR_YEAR , GL.UPPER_LOCGOV_CODE AS UPPER_LOCGOV_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GL.UPPER_LOCGOV_CODE AND CODE_TYPE = 'WDR' AND USE_YN = 'Y') AS UPPER_LOCGOV_NM , GL.LOCGOV_CODE AS LOCGOV_CODE , GL.LOCGOV_NM AS LOCGOV_NM , SUM(GC.CNTR_AMT) AS CNTR_AMT , COUNT(DISTINCT(GC.USER_ID)) AS GIVE_PERSONS , SUM(GC.CNTR_POINT) AS CNTR_POINT , ( SELECT IFNULL(SUM(CNTR_USE_POINT), 0) FROM G_CNTR_USE_POINT a, G_LOCGOV b WHERE use_se_code ='1' AND a.cntr_locgov_code = b.locgov_code AND b.locgov_code = GL.locgov_code
AND cntr_locgov_code = #{shLocgovCode}
AND year(point_use_de) = #{shCntrYear}
) AS CNTR_USE_POINT FROM G_CNTR GC INNER JOIN G_LOCGOV GL ON GC.CNTR_LOCGOV_CODE = GL.LOCGOV_CODE WHERE 1=1 AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND GL.LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) = #{shCntrYear}
GROUP BY year(GC.CNTR_DE) , GL.UPPER_LOCGOV_CODE , GL.LOCGOV_CODE )

/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateList */ SELECT year(GC.CNTR_DE) as CNTR_YEAR , GL.UPPER_LOCGOV_CODE AS UPPER_LOCGOV_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GL.UPPER_LOCGOV_CODE AND CODE_TYPE = 'WDR' AND USE_YN = 'Y') AS UPPER_LOCGOV_NM , GL.LOCGOV_CODE AS LOCGOV_CODE , GL.LOCGOV_NM AS LOCGOV_NM , SUM(GC.CNTR_AMT) AS CNTR_AMT , COUNT(DISTINCT(USER_ID)) AS GIVE_PERSONS , SUM(GC.CNTR_POINT) AS CNTR_POINT , ( SELECT IFNULL(SUM(CNTR_USE_POINT), 0) FROM G_CNTR_USE_POINT a, G_LOCGOV b WHERE use_se_code ='1' AND a.cntr_locgov_code = b.locgov_code AND b.locgov_code = GL.locgov_code
AND cntr_locgov_code = #{shLocgovCode}
AND year(point_use_de) = #{shCntrYear}
) AS CNTR_USE_POINT , COUNT(CNTR_SN) AS GIVE_CNT FROM G_CNTR GC, G_LOCGOV GL WHERE 1=1 AND GC.CNTR_LOCGOV_CODE = GL.LOCGOV_CODE AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND GL.LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) = #{shCntrYear}
GROUP BY year(GC.CNTR_DE) , GL.UPPER_LOCGOV_CODE , GL.LOCGOV_CODE ORDER BY year(GC.CNTR_DE) DESC , GL.UPPER_LOCGOV_CODE , GL.LOCGOV_CODE

/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateDetailSum */ SELECT IFNULL(SUM(CNTR_AMT), 0) AS CNTR_AMT , COUNT(DISTINCT(GC.USER_ID)) AS GIVE_PERSONS , IFNULL(SUM(CNTR_POINT), 0) AS CNTR_POINT FROM G_CNTR GC, OP_USER OU WHERE 1=1 AND GC.USER_ID = OU.USER_ID AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) = #{shCntrYear}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND CNTR_PATH_CODE = '100'
AND CNTR_PATH_CODE IN ('200', '300')
AND OU.USER_NAME = #{shUserName}

/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateDetailListCount */ SELECT COUNT(*) FROM ( SELECT CNTR_DE , OU.USER_NAME , CNTR_AMT , CNTR_POINT , CNTR_PATH_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GC.CNTR_PATH_CODE AND CODE_TYPE = 'CNTR_PATH' AND USE_YN = 'Y') AS CNTR_PATH_NAME FROM G_CNTR GC, OP_USER OU WHERE 1=1 AND GC.USER_ID = OU.USER_ID AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) = #{shCntrYear}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND CNTR_PATH_CODE = '100'
AND CNTR_PATH_CODE IN ('200', '300')
AND OU.USER_NAME = #{shUserName}
)

/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateDetailList */ SELECT A.CNTR_SN , A.CNTR_DE , A.STTEMNT_PAY_DE , A.USER_NAME USER_NAME , A.LOGIN_ID LOGIN_ID , A.CNTR_AMT , A.CNTR_POINT , A.CNTR_PATH_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = A.CNTR_PATH_CODE AND CODE_TYPE = 'CNTR_PATH' AND USE_YN = 'Y') AS CNTR_PATH_NAME , A.RTNPSNT_REQST_CODE , A.ELCTRN_PAY_NO , A.CNTR_REQMNG_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = A.CNTR_REQMNG_CODE AND CODE_TYPE = 'CNTR_REQMNG' AND USE_YN = 'Y') AS CNTR_REQMNG_CODE_NAME , A.REQ_STATUS_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = A.REQ_STATUS_CODE AND CODE_TYPE = 'REQ_STATUS' AND USE_YN = 'Y') AS REQ_STATUS_CODE_NAME , A.FRST_REGIST_PNTTM , A.APPR_DT , (CASE WHEN A.NTS_CNT = 0 THEN '미신고' ELSE '신고' END) AS NTS_STTUS_MSSAGE FROM ( SELECT GC.CNTR_SN , DATE_FORMAT(GC.FRST_REGIST_PNTTM,'%Y-%m-%d %H:%i:%s') AS CNTR_DE , DATE_FORMAT(GC.STTEMNT_PAY_DE,'%Y-%m-%d') AS STTEMNT_PAY_DE , OU.USER_NAME , OU.LOGIN_ID , GC.CNTR_AMT , GC.CNTR_POINT , GC.CNTR_PATH_CODE , GC.RTNPSNT_REQST_CODE , GC.ELCTRN_PAY_NO , GCR.CNTR_REQMNG_CODE , GCR.REQ_STATUS_CODE , DATE_FORMAT(GCR.FRST_REGIST_PNTTM,'%Y-%m-%d %H:%i:%s') AS FRST_REGIST_PNTTM , DATE_FORMAT(GCR.APPR_DT,'%Y-%m-%d %H:%i:%s') AS APPR_DT , IFNULL((SELECT COUNT(ELCTRN_PAY_NO) FROM G_CNTR_TAX_LOG WHERE NTS_RES_CODE = '200' AND ELCTRN_PAY_NO = GC.ELCTRN_PAY_NO), 0) AS NTS_CNT FROM G_CNTR GC LEFT JOIN OP_USER OU ON GC.USER_ID = OU.USER_ID LEFT JOIN ( SELECT A.CNTR_SN, A.CNTR_REQMNG_CODE, A.REQ_STATUS_CODE, A.FRST_REGIST_PNTTM, A.APPR_DT FROM G_CNTR_REQMNG A WHERE A.REQ_STATUS_CODE != '200' AND A.FRST_REGIST_PNTTM = (SELECT MAX(B.FRST_REGIST_PNTTM) FROM G_CNTR_REQMNG B WHERE B.CNTR_SN =A.CNTR_SN) ) GCR ON GC.CNTR_SN = GCR.CNTR_SN WHERE 1=1 AND GC.DELETE_AT = 'N' AND GC.cntr_sttus_code = '200' AND GC.sttemnt_pay_de is not NULL
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) = #{shCntrYear}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND CNTR_PATH_CODE = '100'
AND CNTR_PATH_CODE IN ('200', '300')
AND USER_NAME = #{shUserName}
) A ORDER BY A.CNTR_DE DESC, A.frst_regist_pnttm DESC

		/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateDetailListCountTest */
	    SELECT COUNT(*)
        FROM
        (
		    SELECT
		        CNTR_DE
	                , OU.USER_NAME
	                , CNTR_AMT
	                , CNTR_POINT
	                , CNTR_PATH_CODE
	                , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GC.CNTR_PATH_CODE AND CODE_TYPE = 'CNTR_PATH' AND USE_YN = 'Y') AS CNTR_PATH_NAME
		    FROM G_CNTR GC, OP_USER OU
		    WHERE 1=1
		    AND GC.USER_ID = OU.USER_ID

		    AND CNTR_LOCGOV_CODE = #{shLocgovCode}


		    AND year(GC.CNTR_DE) = #{shCntrYear}


		    AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}



            AND STTEMNT_PAY_DE BETWEEN #{shSttemntPayDeStart} AND #{shSttemntPayDeEnd}




		    AND CNTR_PATH_CODE = '100' 


		    AND CNTR_PATH_CODE IN ('200', '300') 


            AND delete_at = #{shDeleteAt}




					AND USER_NAME = #{shText}


					AND OU.LOGIN_ID = #{shText}


					AND GC.elctrn_pay_no = #{shText}



        )

/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateDetailListTest */ select cntr_sn, cntr_de, A.user_id, cntr_amt, cntr_point, cntr_blce_point, point_end_de, sttemnt_pay_de, pay_valid_de, cntrbtr_opinion_cn, setle_mth_code, cntr_use_purps_code, elctrn_pay_no, seoul_trget_at, rcept_bank_code, rcept_bank_nm, rtnpsnt_reqst_at, info_agre_at, frst_register_id, last_updusr_id , delete_at , IFNULL((SELECT LABEL FROM OP_COMMON_CODE WHERE CODE_TYPE = 'NTS_CODE' AND ID = A.NTS_CODE), '') AS NTS_STTUS_MSSAGE ,(select concat(upper_locgov_nm, ' ', locgov_nm) from g_locgov where locgov_code=A.psitn_locgov_code) as psitn_locgov_code ,(select concat(upper_locgov_nm, ' ', locgov_nm) from g_locgov where locgov_code=A.cntr_locgov_code) as cntr_locgov_code , (A.user_name) user_name , (A.login_id) login_id , (rcepter_nm) rcepter_nm ,(select label from op_common_code where id = cntr_path_code and code_type = 'CNTR_PATH' and use_yn = 'Y') as cntr_path_code ,(select label from op_common_code where id = cntr_sttus_code and code_type = 'CNTR_STTUS' and use_yn = 'Y') as cntr_sttus_code ,(select detail from op_common_code where id = rtnpsnt_reqst_code and code_type = 'RTNPSNT_REQST' and use_yn = 'Y') as rtnpsnt_reqst_code ,to_char(frst_regist_pnttm,'YYYY-MM-DD hh24:mi:ss') as frst_regist_pnttm ,to_char(last_updt_pnttm,'YYYY-MM-DD hh24:mi:ss') as last_updt_pnttm from ( SELECT cntr_sn, cntr_de, GC.user_id, cntr_amt, cntr_point, cntr_blce_point, point_end_de, sttemnt_pay_de, pay_valid_de, cntrbtr_opinion_cn, setle_mth_code, cntr_use_purps_code, elctrn_pay_no, seoul_trget_at, rcept_bank_code, rcept_bank_nm, rtnpsnt_reqst_at, info_agre_at, frst_register_id, last_updusr_id , delete_at , IFNULL((SELECT ELCR_APL_CD FROM G_CNTR_TAX_LOG WHERE NTS_RES_CODE = '200' AND ELCTRN_PAY_NO = GC.ELCTRN_PAY_NO ORDER BY FRST_REGIST_PNTTM DESC LIMIT 1 ), '') AS NTS_CODE ,psitn_locgov_code,cntr_locgov_code ,OU.user_name ,OU.login_id ,rcepter_nm ,cntr_path_code ,cntr_sttus_code ,rtnpsnt_reqst_code ,frst_regist_pnttm ,last_updt_pnttm FROM G_CNTR GC, OP_USER OU WHERE 1=1 AND GC.USER_ID = OU.USER_ID
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) = #{shCntrYear}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND STTEMNT_PAY_DE BETWEEN #{shSttemntPayDeStart} AND #{shSttemntPayDeEnd}
AND CNTR_PATH_CODE = '100'
AND CNTR_PATH_CODE IN ('200', '300')
AND USER_NAME = #{shUserName}
AND delete_at = #{shDeleteAt}
AND USER_NAME = #{shText}
AND OU.LOGIN_ID = #{shText}
AND GC.elctrn_pay_no = #{shText}
ORDER BY cntr_de desc, frst_regist_pnttm desc
) A


	    	/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateDetailListCountCntr */
		    SELECT
				count(*) as cnt
		    FROM G_CNTR GC, OP_USER OU
            WHERE 1=1
            AND GC.USER_ID = OU.USER_ID

            AND cntr_sn = #{shCntrSn}


            AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}


            AND USER_NAME = #{shUserName}


            AND OU.login_id = #{shLoginId}


            AND CNTR_LOCGOV_CODE = #{shLocgovCode}


            AND sttemnt_pay_de = #{shSttemntPayDe}



		    AND CNTR_PATH_CODE = '100' 


		    AND CNTR_PATH_CODE IN ('200', '300') 


            AND cntr_sttus_code = #{shCntrSttusCode}


            AND elctrn_pay_no = #{shElctrnPayNo}

            ORDER BY GC.cntr_sn DESC

/* saleson.shop.give.givestate.GiveStateMapper.getGiveStateDetailListCntr */ SELECT A.cntr_sn , A.cntr_de , A.user_id , A.USER_NAME USER_NAME , A.LOGIN_ID LOGIN_ID , A.psitn_locgov_code , A.cntr_locgov_code , (select concat(upper_locgov_nm, ' ', locgov_nm) from g_locgov where locgov_code=A.psitn_locgov_code) as psitn_locgov_code_name , (select concat(upper_locgov_nm, ' ', locgov_nm) from g_locgov where locgov_code=A.cntr_locgov_code) as cntr_locgov_code_name , A.cntr_amt , A.cntr_point , A.cntr_blce_point , A.point_end_de , A.sttemnt_pay_de , A.pay_valid_de , A.cntr_path_code , A.cntr_sttus_code , A.cntrbtr_opinion_cn , A.setle_mth_code , A.cntr_use_purps_code , A.elctrn_pay_no , A.seoul_trget_at , A.rcept_bank_code , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = A.RCEPT_BANK_CODE AND CODE_TYPE = 'OFF_BANK_LIST' AND USE_YN = 'Y') AS RCEPT_BANK_CODE_NM , A.rcept_bank_nm , A.rcepter_nm rcepter_nm , A.rtnpsnt_reqst_code , A.rtnpsnt_reqst_at , A.info_agre_at , A.frst_register_id , A.frst_regist_pnttm , A.last_updusr_id , A.last_updt_pnttm , A.delete_at , A.nts_sttus_mssage FROM ( SELECT GC.cntr_sn , GC.cntr_de , GC.user_id , OU.USER_NAME , OU.LOGIN_ID , GC.psitn_locgov_code , GC.cntr_locgov_code , GC.cntr_amt , GC.cntr_point , GC.cntr_blce_point , GC.point_end_de , GC.sttemnt_pay_de , GC.pay_valid_de , GC.cntr_path_code , GC.cntr_sttus_code , GC.cntrbtr_opinion_cn , GC.setle_mth_code , GC.cntr_use_purps_code , GC.elctrn_pay_no , GC.seoul_trget_at , GC.rcept_bank_code , GC.rcept_bank_nm , GC.rcepter_nm , GC.rtnpsnt_reqst_code , GC.rtnpsnt_reqst_at , GC.info_agre_at , GC.frst_register_id , GC.frst_regist_pnttm , GC.last_updusr_id , GC.last_updt_pnttm , GC.delete_at , GC.nts_sttus_mssage FROM G_CNTR GC, OP_USER OU WHERE 1=1 AND GC.USER_ID = OU.USER_ID
AND cntr_sn = #{shCntrSn}
AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}
AND USER_NAME = #{shUserName}
AND OU.login_id = #{shLoginId}
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
AND sttemnt_pay_de = #{shSttemntPayDe}
AND CNTR_PATH_CODE = '100'
AND CNTR_PATH_CODE IN ('200', '300')
AND cntr_sttus_code = #{shCntrSttusCode}
AND elctrn_pay_no = #{shElctrnPayNo}
AND delete_at = #{shDeleteAt}
) A ORDER BY GC.cntr_sn desc

mapper.update:
/* saleson.shop.give.givestate.GiveStateMapper.giveCancelProcess */
UPDATE G_CNTR A
SET A.CNTR_POINT = 0
, A.CNTR_BLCE_POINT = 0
, A.STTEMNT_PAY_DE = NULL
, A.POINT_END_DE = NULL
, A.CNTR_STTUS_CODE = '300'
, A.LAST_UPDUSR_ID = #{lastUpdusrId}
, A.LAST_UPDT_PNTTM = DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
, A.DELETE_AT = 'Y'
WHERE
A.ELCTRN_PAY_NO = #{elctrnPayNo}
AND A.USER_ID = #{userId}

	/* saleson.shop.give.givestate.GiveStateMapper.giveDeleteAt */
	UPDATE G_CNTR A
	SET A.DELETE_AT = #{deleteAt}
	, A.LAST_UPDUSR_ID = #{userKey}
	, A.CNTR_BLCE_POINT = 0
	, A.STTEMNT_PAY_DE = NULL
	, A.POINT_END_DE = NULL
	, A.CNTR_STTUS_CODE = '300'
	, A.LAST_UPDUSR_ID = #{userKey}
	, A.LAST_UPDT_PNTTM = DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
 		WHERE
	A.ELCTRN_PAY_NO = #{elctrnPayNo}
	AND A.USER_ID = #{userId}

 	 	/* saleson.shop.give.givestate.GiveStateMapper.givePointRenew */
 		UPDATE G_CNTR A
 			SET
 			  a.cntr_point = (a.cntr_amt * (select point_rate from g_ctbny_setup where locgov_code = a.cntr_locgov_code and stdr_year = DATE_FORMAT(now(), '%Y') )/100 )
 			, a.cntr_blce_point = (a.cntr_amt * (select point_rate from g_ctbny_setup where locgov_code = a.cntr_locgov_code and stdr_year = DATE_FORMAT(now(), '%Y') )/100 )
 			, point_end_de = DATE_FORMAT(ADDDATE(a.cntr_de, interval+5 year), '%Y%m%d')
			, rtnpsnt_reqst_code = '100'
			, LAST_UPDUSR_ID = #{lastUpdusrId}
			, LAST_UPDT_PNTTM = DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
			where A.ELCTRN_PAY_NO = #{elctrnPayNo}

mapper.select:
/* saleson.shop.give.givestate.GiveStateMapper.getGiveReqmngCount */ SELECT COUNT(*) as cnt FROM G_CNTR_REQMNG GCR, OP_MANAGER OM WHERE 1=1 AND GCR.FRST_REGISTER_ID = OM.USER_ID
AND GCR.LOCGOV_CODE = #{shLocgovCode}
AND TO_CHAR(GCR.FRST_REGIST_PNTTM,'YYYYMMDD') BETWEEN #{shFrstRegistPnttmStart} AND #{shFrstRegistPnttmEnd}
AND GCR.CNTR_REQMNG_CODE = #{shCntrReqmngCode} -- 100: 과오납, 200: 포인트생성
AND GCR.REQ_STATUS_CODE = #{shReqStatusCode} -- 100:요청 200:취소 999:승인
AND GCR.USE_YN = 'Y'

/* saleson.shop.give.givestate.GiveStateMapper.getGiveReqmngList */ SELECT a.REQ_ID , a.LOGIN_ID LOGIN_ID , a.USER_NAME USER_NAME , (SELECT USER_ID from op_user where LOGIN_ID = a.LOGIN_ID) AS USER_ID , a.LOCGOV_CODE , (select concat(upper_locgov_nm, ' ', locgov_nm) from g_locgov where locgov_code = a.LOCGOV_CODE) as LOCGOV_CODE_NAME , a.STTEMNT_PAY_DE , a.CNTR_AMT , a.CNTR_REQMNG_CODE , (select label from op_common_code where id = a.CNTR_REQMNG_CODE and code_type = 'CNTR_REQMNG' and use_yn = 'Y') as CNTR_REQMNG_CODE_NAME , a.DISCRIPTION , (SELECT LOGIN_ID FROM op_manager WHERE USER_ID = a.FRST_REGISTER_ID) AS FRST_REGISTER_ID , a.FRST_REGIST_PNTTM , (SELECT LOGIN_ID FROM op_manager WHERE USER_ID = a.LAST_UPDUSR_ID) AS LAST_UPDUSR_ID , a.LAST_UPDT_PNTTM , a.APPR_DT , a.CANCLE_DT , a.REQ_STATUS_CODE , (select label from op_common_code where id = a.REQ_STATUS_CODE and code_type = 'REQ_STATUS' and use_yn = 'Y') as REQ_STATUS_CODE_NAME , a.CNTR_SN , (select elctrn_pay_no from g_cntr where cntr_sn = a.CNTR_SN) as ELCTRN_PAY_NO , (select cntr_blce_point from g_cntr WHERE cntr_sn = a.CNTR_SN) as CNTR_BLCE_POINT , (select link_instt_cd from g_cntr where cntr_sn = a.CNTR_SN) as LINK_INSTT_CD FROM ( SELECT GCR.REQ_ID , GCR.LOGIN_ID , GCR.USER_NAME , GCR.LOCGOV_CODE , GCR.STTEMNT_PAY_DE , GCR.CNTR_AMT , GCR.CNTR_REQMNG_CODE , GCR.DISCRIPTION , GCR.FRST_REGISTER_ID , DATE_FORMAT(GCR.FRST_REGIST_PNTTM,'%Y-%m-%d %H:%i:%s') AS FRST_REGIST_PNTTM , GCR.LAST_UPDUSR_ID , GCR.LAST_UPDT_PNTTM , DATE_FORMAT(GCR.APPR_DT,'%Y-%m-%d %H:%i:%s') AS APPR_DT , DATE_FORMAT(GCR.CANCLE_DT,'%Y-%m-%d %H:%i:%s') AS CANCLE_DT , GCR.REQ_STATUS_CODE , GCR.CNTR_SN FROM G_CNTR_REQMNG GCR WHERE 1=1
AND GCR.LOCGOV_CODE = #{shLocgovCode}
AND TO_CHAR(GCR.FRST_REGIST_PNTTM,'YYYYMMDD') BETWEEN #{shFrstRegistPnttmStart} AND #{shFrstRegistPnttmEnd}
AND GCR.CNTR_REQMNG_CODE = #{shCntrReqmngCode}
AND GCR.REQ_STATUS_CODE = #{shReqStatusCode}
AND GCR.USE_YN = 'Y' ORDER BY (CASE WHEN GCR.LAST_UPDT_PNTTM IS NULL THEN 1 ELSE 2 END ), GCR.REQ_ID DESC
) a

mapper.update:
		/* saleson.shop.give.givestate.GiveStateMapper.giveReqmngApprove */
 		UPDATE G_CNTR_REQMNG A
 		SET
	 			A.LAST_UPDUSR_ID = #{lastUpdusrId}
	 		, 	A.LAST_UPDT_PNTTM = DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
	 		, 	A.REQ_STATUS_CODE = '999'
	 		, 	A.APPR_DT = DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
 	 	WHERE
 		A.REQ_ID = #{reqId}

 		/* saleson.shop.give.givestate.GiveStateMapper.giveReqmngCancel */
 	 	UPDATE G_CNTR_REQMNG A
 	 	SET
	 	 		A.LAST_UPDUSR_ID = #{lastUpdusrId}
	 		, 	A.LAST_UPDT_PNTTM = DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
	 		, 	A.REQ_STATUS_CODE = '200'
	 		, 	A.CANCLE_DT = DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
 	 	WHERE
 		REQ_ID = #{reqId}

/* saleson.shop.give.givestate.GiveStateMapper.sunapCancel */
UPDATE G_CNTR A
SET A.CNTR_POINT = 0
, A.CNTR_BLCE_POINT = 0
, A.STTEMNT_PAY_DE = NULL
, A.POINT_END_DE = NULL
, A.CNTR_STTUS_CODE = '100'
, A.LAST_UPDUSR_ID = #{lastUpdusrId}
