SELECT GC.CNTR_SN , GC.STTEMNT_PAY_DE , GC.USER_ID , GC.CNTR_STTUS_CODE , OU.MBER_CI , GC.CNTR_AMT , GC.ELCTRN_PAY_NO , GL.BIZRNO AS BIZ_NO , (SELECT ELCR_APL_CD FROM G_CNTR_TAX_TEMP WHERE ELCTRN_PAY_NO = GC.ELCTRN_PAY_NO LIMIT 1) AS ELCR_APL_CD , (SELECT COUNT(*) FROM G_CNTR_TAX_LOG WHERE ELCTRN_PAY_NO = GC.ELCTRN_PAY_NO AND ELCR_APL_CD = '03') AS LOG_CNT FROM G_CNTR GC LEFT OUTER JOIN G_LOCGOV GL ON GL.LOCGOV_CODE = GC.CNTR_LOCGOV_CODE LEFT OUTER JOIN OP_USER OU ON OU.USER_ID = GC.USER_ID WHERE 1=1
AND GC.CNTR_SN = #{cntrSn}
AND GC.ELCTRN_PAY_NO = #{elctrnPayNo}
AND GC.STTEMNT_PAY_DE IS NOT NULL AND GC.CNTR_STTUS_CODE = #{cntrSttusCode} AND GC.DELETE_AT = 'N'

